import React, { useRef, useState, useEffect } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { OrbitControls, Environment, ContactShadows, Html, useGLTF } from '@react-three/drei';
import * as THREE from 'three';

interface VirtualInterviewerProps {
  state: 'idle' | 'speaking' | 'listening' | 'thinking' | string;
  onSpeakComplete?: () => void;
}

// Placeholder avatar component (will be replaced with Ready Player Me avatar)
function InterviewerAvatar({ state }: { state: string }) {
  const groupRef = useRef<THREE.Group>(null);
  const headRef = useRef<THREE.Mesh>(null);

  useFrame((state) => {
    if (groupRef.current) {
      // Subtle breathing animation
      const time = state.clock.getElapsedTime();
      groupRef.current.position.y = Math.sin(time * 2) * 0.01;

      // Head movement based on state
      if (headRef.current) {
        if (state === 'speaking') {
          headRef.current.rotation.y = Math.sin(time * 3) * 0.1;
        } else if (state === 'listening') {
          headRef.current.rotation.y = Math.sin(time * 1.5) * 0.05;
          headRef.current.rotation.x = Math.sin(time * 2) * 0.02;
        } else if (state === 'thinking') {
          headRef.current.rotation.x = 0.2;
          headRef.current.rotation.z = Math.sin(time * 2) * 0.05;
        }
      }
    }
  });

  return (
    <group ref={groupRef} position={[0, 0, 0]}>
      {/* Head */}
      <mesh ref={headRef} position={[0, 1.7, 0]}>
        <sphereGeometry args={[0.2, 32, 32]} />
        <meshStandardMaterial color="#e0ac69" />
      </mesh>

      {/* Body - Formal shirt */}
      <mesh position={[0, 1.2, 0]}>
        <boxGeometry args={[0.5, 0.8, 0.3]} />
        <meshStandardMaterial color="#ffffff" />
      </mesh>

      {/* Blazer */}
      <mesh position={[0, 1.1, 0.1]}>
        <boxGeometry args={[0.55, 0.7, 0.15]} />
        <meshStandardMaterial color="#1a1a2e" />
      </mesh>

      {/* Left arm */}
      <mesh position={[-0.35, 1.0, 0]}>
        <boxGeometry args={[0.12, 0.6, 0.12]} />
        <meshStandardMaterial color="#1a1a2e" />
      </mesh>

      {/* Right arm */}
      <mesh position={[0.35, 1.0, 0]}>
        <boxGeometry args={[0.12, 0.6, 0.12]} />
        <meshStandardMaterial color="#1a1a2e" />
      </mesh>

      {/* Eyes */}
      <mesh position={[-0.07, 1.75, 0.18]}>
        <sphereGeometry args={[0.03, 16, 16]} />
        <meshStandardMaterial color="#ffffff" />
      </mesh>
      <mesh position={[0.07, 1.75, 0.18]}>
        <sphereGeometry args={[0.03, 16, 16]} />
        <meshStandardMaterial color="#ffffff" />
      </mesh>

      {/* Pupils */}
      <mesh position={[-0.07, 1.75, 0.2]}>
        <sphereGeometry args={[0.015, 16, 16]} />
        <meshStandardMaterial color="#000000" />
      </mesh>
      <mesh position={[0.07, 1.75, 0.2]}>
        <sphereGeometry args={[0.015, 16, 16]} />
        <meshStandardMaterial color="#000000" />
      </mesh>
    </group>
  );
}

// Interview room environment
function InterviewRoom() {
  return (
    <>
      {/* Floor */}
      <mesh rotation={[-Math.PI / 2, 0, 0]} position={[0, 0, 0]} receiveShadow>
        <planeGeometry args={[20, 20]} />
        <meshStandardMaterial color="#8b7355" />
      </mesh>

      {/* Back wall */}
      <mesh position={[0, 2.5, -5]}>
        <boxGeometry args={[20, 5, 0.5]} />
        <meshStandardMaterial color="#f5f5dc" />
      </mesh>

      {/* Side walls */}
      <mesh position={[-10, 2.5, 0]} rotation={[0, Math.PI / 2, 0]}>
        <boxGeometry args={[20, 5, 0.5]} />
        <meshStandardMaterial color="#f5f5dc" />
      </mesh>
      <mesh position={[10, 2.5, 0]} rotation={[0, Math.PI / 2, 0]}>
        <boxGeometry args={[20, 5, 0.5]} />
        <meshStandardMaterial color="#f5f5dc" />
      </mesh>

      {/* Desk */}
      <mesh position={[0, 0.75, 2]}>
        <boxGeometry args={[3, 0.1, 1.5]} />
        <meshStandardMaterial color="#4a3728" />
      </mesh>

      {/* Desk legs */}
      <mesh position={[-1.3, 0.375, 0.6]}>
        <boxGeometry args={[0.1, 0.75, 0.1]} />
        <meshStandardMaterial color="#4a3728" />
      </mesh>
      <mesh position={[1.3, 0.375, 0.6]}>
        <boxGeometry args={[0.1, 0.75, 0.1]} />
        <meshStandardMaterial color="#4a3728" />
      </mesh>
      <mesh position={[-1.3, 0.375, -0.6]}>
        <boxGeometry args={[0.1, 0.75, 0.1]} />
        <meshStandardMaterial color="#4a3728" />
      </mesh>
      <mesh position={[1.3, 0.375, -0.6]}>
        <boxGeometry args={[0.1, 0.75, 0.1]} />
        <meshStandardMaterial color="#4a3728" />
      </mesh>

      {/* Lighting */}
      <ambientLight intensity={0.5} />
      <directionalLight position={[5, 10, 5]} intensity={1} castShadow />
      <pointLight position={[-5, 5, -5]} intensity={0.5} />
    </>
  );
}

// State indicator
function StateIndicator({ state }: { state: string }) {
  const getStateText = () => {
    switch (state) {
      case 'speaking': return '🗣️ Speaking...';
      case 'listening': return '👂 Listening...';
      case 'thinking': return '🤔 Thinking...';
      default: return '😊 Ready';
    }
  };

  const getStateColor = () => {
    switch (state) {
      case 'speaking': return 'bg-blue-500';
      case 'listening': return 'bg-green-500';
      case 'thinking': return 'bg-yellow-500';
      default: return 'bg-gray-500';
    }
  };

  return (
    <div className="absolute top-4 left-1/2 transform -translate-x-1/2">
      <div className={`${getStateColor()} text-white px-6 py-2 rounded-full shadow-lg`}>
        {getStateText()}
      </div>
    </div>
  );
}

